#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 8 + 1, q = r() % 10 + 1; printf("%d %d\n", n, q); for (int i = 0; i < n; i++) printf("%d ", int(r() % 4) + 1); puts(""); while (q--) { if (r() % 2) printf("1 %d %d\n", int(r() % n) + 1, int(r() % 4) + 1); else { int l = r() % n + 1, rr = r() % n + 1; if (l > rr) std::swap(l, rr); printf("2 %d %d\n", l, rr); } } }
